<script setup lang="ts">
import {computed,onBeforeUnmount,ref,shallowRef,watch,useId} from 'vue'
import {api} from '../api/client'
import {session,can,contextGeneration,switchingTenant} from '../stores/session'
import {createDeliveryJournalReader,emptyDeliveryRead,deliveryUuid,recordedStatusLabels,type DeliveryCursor,type AttentionStatus} from '../utils/deliveryJournal'
import {displayTime} from '../utils/display'
import ApiErrorNotice from './ApiErrorNotice.vue'
import DeliveryDeadLetterPanel from './DeliveryDeadLetterPanel.vue'
const heading=useId(),state=shallowRef(emptyDeliveryRead()),pool=ref(''),pageSize=ref(10),selectedId=ref(''),command=ref(''),reader=createDeliveryJournalReader(api,s=>state.value=s)
const status=ref<'ALL'|AttentionStatus>('ALL')
const permitted=computed(()=>session.value?.mode==='remote_test'&&session.value.user.role==='padmin'&&can('ticket_notes:read_internal')&&can('audit:read')&&!switchingTenant.value)
const current=computed(()=>state.value.detail?.entry??state.value.recovery?.current)
const channels:Record<string,string>={EMAIL:'邮件',SMS:'短信',DINGTALK:'钉钉',WECHAT_WORK:'企业微信',WEBHOOK:'Webhook',VOICE:'语音'}
const kinds:Record<string,string>={QUEUE:'排队声明',START:'请求开始记录',DEAD_LETTER:'死信处置记录',RECEIPT:'回执声明'}
watch(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.permission_version,session.value?.account_version,session.value?.capabilities,permitted.value]),()=>{selectedId.value='';command.value='';pool.value='';reader.reset(permitted.value?{tenant:session.value!.tenant.id,actor:session.value!.user.id,permissionVersion:session.value!.permission_version}:null)},{immediate:true,flush:'sync'})
watch([pool,pageSize,status],()=>{selectedId.value='';command.value='';reader.reset(permitted.value?{tenant:session.value!.tenant.id,actor:session.value!.user.id,permissionVersion:session.value!.permission_version}:null)},{flush:'sync'})
function list(cursor:DeliveryCursor|null=null){if(state.value.busy)return;selectedId.value='';command.value='';return reader.load({kind:'list',pool:pool.value||null,size:pageSize.value,cursor,...(status.value==='ALL'?{}:{attention:status.value})})}
async function detail(id:string,before:number|null=null){if(state.value.busy)return;selectedId.value=id;command.value='';if(await reader.load({kind:'detail',id,size:100,before}))command.value=state.value.detail?.entry.last_start_command_id??state.value.detail?.history.at(-1)?.command_id??''}
function recover(id:string=command.value){if(state.value.busy)return;if(!deliveryUuid(selectedId.value)||!deliveryUuid(id))return;command.value=id;return reader.load({kind:'recover',id:selectedId.value,command:id})}
onBeforeUnmount(reader.dispose)
</script>
<template><section v-if="permitted" class="proto-panel delivery-journal" :aria-labelledby="heading" :aria-busy="state.busy"><h2 :id="heading">投递日志与原命令核对</h2>
 <form class="actions" @submit.prevent="list()"><label>资源池 ID（可选）<input v-model="pool" maxlength="36" :disabled="state.busy" /></label><label>每页<select v-model.number="pageSize" :disabled="state.busy"><option :value="1">1</option><option :value="5">5</option><option :value="10">10</option><option :value="20">20</option></select></label><button :disabled="state.busy||!!pool&&!deliveryUuid(pool)">读取日志</button><button v-if="state.busy" type="button" @click="reader.cancel">取消读取</button><button v-if="state.target&&(state.error||state.cancelled)&&!state.busy" type="button" @click="reader.retry">重试原读取</button></form>
 <label>日志范围<select v-model="status" :disabled="state.busy"><option value="ALL">全部日志</option><option value="ATTENTION">待核对（结果不明 / 失败 / 死信）</option><option value="UNKNOWN">结果不明</option><option value="FAILED">失败记录</option><option value="DEAD_LETTER">死信记录</option></select></label>
 <small>仅本地 V50 记录；状态不等于供应商认证，本页不查询供应商、不发送或重试。待核对清单先核验完整授权范围再筛选，超过技术预算时拒绝截断显示，请缩小资源池范围。</small><ApiErrorNotice :error="state.error" guidance="未配置或未找到本地命令不表示供应商未收到，请勿据此重新发送。"/><p v-if="state.busy||state.cancelled" role="status">{{state.busy?'正在核对授权范围与完整日志链…':'已取消读取并清空旧结果。'}}</p>
 <template v-if="state.page"><p role="status">{{status==='ALL'?'当前授权池范围共':'当前筛选完整匹配'}} {{state.page.total_count}} 条本地投递日志。</p><p v-if="!state.page.items.length">当前页没有本地日志，不能据此断言供应商未收到消息。</p><div v-else class="table-scroll" role="region" aria-label="投递日志，可横向滚动" tabindex="0"><table><thead><tr><th>渠道 / 投递</th><th>记录状态</th><th>尝试 / 回执数</th><th>首次入账</th><th>操作</th></tr></thead><tbody><tr v-for="entry in state.page.items" :key="entry.delivery_id"><td>{{channels[entry.channel]}}<br>{{entry.delivery_id}}</td><td>{{recordedStatusLabels[entry.recorded_status]}}</td><td>{{entry.attempt_count}} / {{entry.receipt_count}}</td><td>{{displayTime(entry.first_recorded_at)}}</td><td><button :disabled="state.busy" @click="detail(entry.delivery_id)">查看历史</button></td></tr></tbody></table></div><button v-if="state.page.next" :disabled="state.busy" @click="list(state.page.next)">下一页</button></template>
 <DeliveryDeadLetterPanel :entry="current??null" @changed="detail($event)" />
 <section v-if="current" aria-label="投递日志详情"><h3>{{channels[current.channel]}} · {{recordedStatusLabels[current.recorded_status]}}</h3><p>{{current.delivery_id}} · 日志版本 {{current.version}} · 送达认证：未核验</p><p>原请求：{{current.last_request_id??'尚无开始记录'}}；资源池：{{current.resource_pool_id}}</p><form class="actions" @submit.prevent="recover()"><label>原命令 ID<input v-model="command" maxlength="36" :disabled="state.busy" /></label><button :disabled="state.busy||!deliveryUuid(command)">只读核对原命令</button><button type="button" :disabled="state.busy" @click="detail(current.delivery_id)">读取最新历史</button></form>
 <template v-if="state.detail"><div class="table-scroll" role="region" aria-label="不可变命令历史，可横向滚动" tabindex="0"><table><thead><tr><th>版本 / 类型</th><th>请求 / 回执声明</th><th>数据库入账</th><th>原命令</th></tr></thead><tbody><tr v-for="step in state.detail.history" :key="step.command_id"><td>{{step.version}} · {{kinds[step.kind]}}</td><td>{{step.request_id??'—'}}<br>{{step.recorded_receipt_status?recordedStatusLabels[step.recorded_receipt_status]:'—'}}</td><td>{{displayTime(step.recorded_at)}}</td><td><button :disabled="state.busy" @click="recover(step.command_id)">核对这条命令</button></td></tr></tbody></table></div><button v-if="state.detail.next_before_version!==null" :disabled="state.busy" @click="detail(current.delivery_id,state.detail.next_before_version)">更早历史</button></template>
 <section v-if="state.recovery" aria-label="原命令核对结果"><p role="status">已找到本地原命令，未查询供应商，不授权重新发送。</p><p>{{state.recovery.original.command_id}} · 原应用版本 {{state.recovery.original.version}} · {{kinds[state.recovery.original.kind]}}</p><p>原请求 ID：{{state.recovery.original.request_id??'此命令不包含请求ID'}}</p></section>
 </section>
</section></template>
<style scoped>.delivery-journal{min-width:0;overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;align-items:end;gap:8px}label{display:flex;flex-direction:column;gap:4px}.table-scroll{max-width:100%;overflow:auto}table{min-width:680px;width:100%;text-align:left;border-collapse:collapse}th,td{padding:8px;vertical-align:top;border-bottom:1px solid #e2e8f0}button{min-height:32px}</style>
